/* Generated by Trae Work */
/* 学习进度线：每门课一条进度线（游标位置/进度条/考前完成率/校准/主线切换）+ 课程合集设置。
   页面已并入 study.html；旧节次课表引擎已彻底移除，今日任务由 cursor.js 游标引擎生成 */
"use strict";
(function () {
  /* ================= 考期与阶段 ================= */
  const KAoyanTarget = SITE_DATA.countdown.kaoyan_target; // 2027-12-19
  function kaoyanStage() {
    const now = new Date(); const tgt = new Date(KAoyanTarget + "T00:00:00");
    const months = (tgt.getFullYear() - now.getFullYear()) * 12 + (tgt.getMonth() - now.getMonth());
    if (months > 6) return "basic";
    if (months > 3) return "enhance";
    return "sprint";
  }
  function nextZikaoWeeks() {
    try { const ev = nextZikaoDate(); return ev ? Math.max(0, Math.floor(daysUntil(ev.date_start) / 7)) : null; }
    catch (e) { return null; }
  }

  /* ================= 渲染：每课一条进度线 ================= */
  function render() {
    const view = document.getElementById("sch-view");
    if (!view) return;
    const pool = CursorAPI.coursePool();
    const main = CursorAPI.mainCourse();
    const weeks = nextZikaoWeeks();
    const stage = kaoyanStage();

    let head = `<div class="sched-day-title">学习进度线</div>
      <p class="desc">每门课一条进度线：指针在哪，今日计划就从哪顺延；任务顺序按考前完成率紧迫度自动排（最危险先学）。考研阶段：<strong>${stage === "basic" ? "基础期" : stage === "enhance" ? "强化期" : "冲刺期"}</strong>
      · 自考下次考期：<strong>${weeks === null ? "待公布（未公布时按 4 月第 2 个周六 / 10 月最后一个周六推算）" : `距考 ${weeks} 周`}</strong><br>
      课程合集：<strong>${pool.length ? pool.map(CursorAPI.poolLabel).join("、") : "未选择"}</strong></p>`;

    if (!pool.length) {
      view.innerHTML = head + `<div class="notice ref"><strong>请在下方「课程合集」中选择科目。</strong>未选择时不生成进度线。</div>`;
      renderSettings();
      return;
    }

    view.innerHTML = head + pool.map(code => lineHtml(code, code === main)).join("");
    bindLineActions(view);
    renderSettings();
  }

  function lineHtml(code, isMain) {
    const units = CursorAPI.unitsOf(code);
    const cur = CursorAPI.cursorOf(code);
    const f = CursorAPI.forecast(code);
    const exam = CursorAPI.examDateOf(code);
    const pct = Math.round(cur / Math.max(1, units.length) * 100);
    const pos = cur < units.length ? units[cur].title : "全部单元已学完";
    const next = cur + 1 < units.length ? units[cur + 1].title : "";
    const plan = CursorAPI.todayQuota();
    const quota = code === plan.main ? plan.mainQuota : 1;
    const pace = f.percentByExam === null ? "" : (f.onTrack
      ? `按当前速度预计 <strong>${f.finishDate}</strong> 学完，进度正常`
      : `<strong class="cursor-warn">按当前速度考前约完成 ${f.percentByExam}%，建议加快或校准</strong>`);
    return `<div class="course-line${isMain ? " is-main" : ""}">
      <div class="cl-head">
        <div class="cl-title">${CursorAPI.poolLabel(code)}${isMain ? `<span class="badge ok">主线</span>` : ""}</div>
        <div class="cl-stats">${cur}/${units.length} 个单元 · 今日 ${cur >= units.length ? "复盘" : quota + " 个任务"} · 考期 <strong>${exam ? exam.date : "—"}</strong>${exam && !exam.confirmed ? "（推算）" : ""}</div>
      </div>
      <div class="prog big"><div class="prog-fill" style="width:${pct}%"></div></div>
      <div class="cl-pos">当前位置：<strong>${pos}</strong>${next ? ` · 下一单元：${next}` : ""}</div>
      <div class="cl-meta">${pace}</div>
      <div class="cl-ops">
        ${isMain ? "" : `<button class="btn small ghost" data-main="${code}">设为主线</button>`}
        <select class="cursor-cal" data-cal="${code}">
          <option value="">校准游标…</option>
          ${units.map(u => `<option value="${u.idx}">${u.idx === cur ? "▶ " : ""}${u.idx + 1}. ${u.title}</option>`).join("")}
        </select>
      </div>
    </div>`;
  }

  function bindLineActions(root) {
    root.querySelectorAll("button[data-main]").forEach(btn => btn.addEventListener("click", () => {
      CursorAPI.setMainCourse(btn.dataset.main);
      render();
    }));
    root.querySelectorAll("select.cursor-cal").forEach(sel => sel.addEventListener("change", () => {
      const code = sel.dataset.cal, v = sel.value;
      if (v === "") return;
      const units = CursorAPI.unitsOf(code);
      const u = units[+v];
      if (!u) return;
      if (!confirm(`校准「${CursorAPI.poolLabel(code)}」：此前 ${v} 个单元视为已完成，今天从「${u.title}」开始。确定？`)) return;
      CursorAPI.setCursor(code, +v);
      render();
    }));
  }

  /* ================= 设置面板：课程合集 + 主线课程 ================= */
  function renderSettings() {
    const list = document.getElementById("zk-subject-list");
    const sel = Store.get("zk_subjects", []);
    if (!list.dataset.built) {
      list.innerHTML = zkSelectableCourses().map(c =>
        `<label><input type="checkbox" value="${c.code}" ${sel.includes(c.code) ? "checked" : ""}> ${c.code} ${c.name}（${c.has_syllabus ? "官方大纲" : "参考章节"}）</label>`).join("");
      list.addEventListener("change", () => {
        const checked = [...list.querySelectorAll("input:checked")].map(i => i.value);
        if (checked.length > 4) {
          alert("黑龙江自考每次最多报考 4 门。");
          list.querySelector(`input[value="${checked[checked.length - 1]}"]`).checked = false;
        }
      });
      list.dataset.built = "1";
    }
    document.getElementById("zk-subject-save").onclick = () => {
      const checked = [...list.querySelectorAll("input:checked")].map(i => i.value);
      if (checked.length > 0 && checked.length < 2) { alert("自考科目至少选择 2 门（每次最多 4 门）"); return; }
      Store.set("zk_subjects", checked);
      render();
    };

    /* 考研科目合集 */
    const kyList = document.getElementById("ky-subject-list");
    const ky = Store.get("ky_subjects", ["数二", "英二", "408"]);
    if (!kyList.dataset.built) {
      kyList.innerHTML = [
        ["数二", "数学（二）（150 分）"],
        ["英二", "英语（二）（100 分）"],
        ["408", "408 计算机学科专业基础综合（150 分，按四门子科章节顺序推进）"]
      ].map(([v, label]) => `<label><input type="checkbox" value="${v}" ${ky.includes(v) ? "checked" : ""}> ${label}</label>`).join("");
      kyList.dataset.built = "1";
    }
    document.getElementById("ky-subject-save").onclick = () => {
      const checked = [...kyList.querySelectorAll("input:checked")].map(i => i.value);
      if (!checked.length) { alert("考研科目至少保留 1 门；如完全不备考研请全部取消并同时清空自考科目。"); return; }
      Store.set("ky_subjects", checked);
      if (!checked.includes(Store.get("main_course", ""))) Store.set("main_course", "");
      render();
    };

    /* 主线课程（每日任务量最大、优先推进） */
    const psel = document.getElementById("priority-select");
    const pool = CursorAPI.coursePool();
    const cur = CursorAPI.mainCourse();
    psel.innerHTML = pool.map(c => `<option value="${c}" ${c === cur ? "selected" : ""}>${CursorAPI.poolLabel(c)}</option>`).join("");
    document.getElementById("priority-save").onclick = () => {
      if (!psel.value) { alert("请先选择课程合集。"); return; }
      CursorAPI.setMainCourse(psel.value);
      render();
    };

    document.getElementById("sch-reset").onclick = () => {
      if (!confirm("清空所有进度线本地记录（选科/合集保留，游标归零）？")) return;
      ["block_overrides", "block_moves", "course_cursor", "skipped_units"].forEach(k => Store.del(k));
      render();
    };
  }

  function zkSelectableCourses() {
    return SITE_DATA.zikao.courses.filter(c => c.chapters || c.reference_chapters);
  }

  /* ================= 事件 ================= */
  document.addEventListener("DOMContentLoaded", () => {
    if (!document.getElementById("sch-view")) return; // 非进度页跳过
    render();
  });
})();
